import {NextResponse} from 'next/server';import { admin } from '../../../lib/supabase';import { score } from '../../../lib/scoring';import OpenAI from 'openai';
export async function GET(req:Request){const id=new URL(req.url).searchParams.get('id')!;const db=admin();const [{data:couple},{data:answers}]=await Promise.all([db.from('couples').select('*').eq('id',id).single(),db.from('answers').select('*').eq('couple_id',id)]);if(!couple?.partner_a_completed||!couple?.partner_b_completed)return NextResponse.json({waiting:true,couple});const base=score(answers||[]);return NextResponse.json({couple,...base})}
export async function POST(req:Request){const {coupleId}=await req.json();const db=admin();const {data:existing}=await db.from('reports').select('*').eq('couple_id',coupleId).maybeSingle();if(existing)return NextResponse.json(existing);const [{data:couple},{data:answers}]=await Promise.all([db.from('couples').select('*').eq('id',coupleId).single(),db.from('answers').select('*').eq('couple_id',coupleId)]);if(!couple?.paid)return NextResponse.json({error:'payment_required'},{status:402});const base=score(answers||[]);if(!process.env.OPENAI_API_KEY)return NextResponse.json({error:'OPENAI_API_KEY is missing'},{status:503});const ai=new OpenAI({apiKey:process.env.OPENAI_API_KEY});const completion=await ai.chat.completions.create({model:process.env.OPENAI_MODEL||'gpt-5-mini',response_format:{type:'json_object'},messages:[{role:'system',content:'Ты создаёшь нейтральный разбор ответов пары. Не ставь диагнозы, не решай кто прав, не говори совместимы ли они и не рекомендуй расставание. Используй только данные. Верни JSON с ключами summary, strengths (array), differences (array), understanding (string), discuss (array из 5 вопросов), experiment (string). Пиши конкретно и бережно.'},{role:'user',content:JSON.stringify({names:[couple.partner_a_name,couple.partner_b_name],...base})}]});const report=JSON.parse(completion.choices[0].message.content||'{}');const {data}=await db.from('reports').insert({couple_id:coupleId,report_json:report}).select().single();return NextResponse.json(data)}
